def main():
    pot = polib.pofile(str(ROOT / "bas_cpp.pot"))
    pot_ids = {e.msgid for e in pot if e.msgid}
    uncovered = sorted(pot_ids - set(T.keys()))
    if uncovered:
        print("ERROR: T missing", len(uncovered), "msgids from bas_cpp.pot")
        for m in uncovered[:20]:
            print("  ", repr(m[:80]))
        raise SystemExit(1)

    for lang in LANGS:
        path = ROOT / f"{lang}.po"
        po = polib.pofile(str(path))
        if po.metadata.get("Language") != lang:
            po.metadata["Language"] = lang
        missing = []
        filled = 0
        for e in po:
            if not e.msgid:
                continue
            row = T.get(e.msgid)
            if not row or lang not in row or not row[lang]:
                missing.append(e.msgid[:60])
                continue
            e.msgstr = row[lang]
            if "fuzzy" in e.flags:
                e.flags.remove("fuzzy")
            filled += 1
        po.save()
        print(lang, "filled", filled, "missing", len(missing))
        for m in missing[:20]:
            print("  MISSING", repr(m))
        if missing:
            raise SystemExit(f"{lang} still has missing translations")


if __name__ == "__main__":
    main()
